import json
import os

# Base structured menu database
menus = []
current_id = 1

def add_menu(name, category, sub_category, meal_types, price_level, est_price, cook_time, spicy, soup, rice, noodle, meat, healthy, delivery, tags):
    global current_id
    menus.append({
        "id": f"menu_{current_id:03d}",
        "name": name,
        "category": category,
        "subCategory": sub_category,
        "mealType": meal_types,
        "priceLevel": price_level,
        "estimatedPrice": est_price,
        "cookingTime": cook_time,
        "spicy": spicy,
        "soup": soup,
        "rice": rice,
        "noodle": noodle,
        "meat": meat,
        "healthy": healthy,
        "deliveryAvailable": delivery,
        "tags": tags
    })
    current_id += 1

